CREATE DATABASE IF NOT EXISTS healthcare_db;USE healthcare_db;CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(100) NOT NULL,email VARCHAR(120) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);CREATE TABLE doctors(id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(100) NOT NULL,qualification VARCHAR(100) NOT NULL,specialist VARCHAR(100) NOT NULL,email VARCHAR(120) NOT NULL UNIQUE,phone VARCHAR(20) NOT NULL,password_hash VARCHAR(100) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);CREATE TABLE admins(id INT AUTO_INCREMENT PRIMARY KEY,email VARCHAR(120) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL);CREATE TABLE appointments(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,doctor_id INT NOT NULL,patient_name VARCHAR(100) NOT NULL,gender VARCHAR(20) NOT NULL,age INT NOT NULL,appointment_date DATE NOT NULL,email VARCHAR(120) NOT NULL,phone VARCHAR(20) NOT NULL,disease VARCHAR(255) NOT NULL,address VARCHAR(500) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'PENDING',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(doctor_id) REFERENCES doctors(id) ON DELETE CASCADE);CREATE TABLE consultations(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,doctor_id INT NOT NULL,requested_date DATETIME NOT NULL,mode VARCHAR(20) NOT NULL,reason VARCHAR(500) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'REQUESTED',meeting_link VARCHAR(500),doctor_notes TEXT,prescription TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(doctor_id) REFERENCES doctors(id) ON DELETE CASCADE);INSERT INTO admins(email,password_hash) VALUES('admin@digitalcare.com','e86f78a8a3caf0b60d8e74e5942aa6d86dc150cd3c03338aef25b7d2d7e3acc7');